'use strict';

/**
* Compute a sample covariance incrementally, ignoring `NaN` values.
*
* @module @stdlib/stats-incr-nancovariance
*
* @example
* var nancovariance = require( '@stdlib/stats-incr-nancovariance' );
*
* var acc = nancovariance();
*
* var cov = acc();
* // returns null
*
* // Covariance is undefined for a single pair:
* cov = acc( 2.0, 1.0 );
* // returns null
*
* // An input pair containing NaN is ignored:
* cov = acc( NaN, 5.0 );
* // returns null
*
* cov = acc( 4.0, 5.0 );
* // returns 4.0
*
* cov = acc();
* // returns 4.0
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
